using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Video;
[InitializeOnLoad]public static class VoyagePresentationSetup {
 static VoyagePresentationSetup(){EditorApplication.update+=Poll;}
 static void Poll(){const string p="Temp/voyage-ui-command.txt";if(!File.Exists(p)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;string command=File.ReadAllText(p).Trim();File.Delete(p);try{if(command=="apply")Apply();if(command=="wide")VoyageGameView.Wide();if(command=="menu"){EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");EditorApplication.isPlaying=true;}if(command=="ship"){EditorSceneManager.OpenScene(StorySceneJourney.ShipPath);EditorApplication.isPlaying=true;}if(command=="stop")EditorApplication.isPlaying=false;if(command=="sailingtest")VoyageSailingCheck.Begin();if(command=="finalflowtest")VoyageFinalFlowCheck.Begin();if(command=="polishtest")VoyagePolishCheck.Begin();if(command=="flowtest")VoyageFinalFlowCheck.Begin();if(command=="test")VoyagePresentationCheck.Begin();if(command=="journeytest")VoyageFinalFlowCheck.Begin();if(command=="shot")ScreenCapture.CaptureScreenshot("Tools/MenuPortraitUpdate/current.png");File.WriteAllText("Tools/MenuPortraitUpdate/status.txt",command+" OK");}catch(Exception e){File.WriteAllText("Tools/MenuPortraitUpdate/status.txt",e.ToString());Debug.LogException(e);}}
 static void Apply(){if(EditorApplication.isPlaying)throw new Exception("Exit Play Mode first");PlayerSettings.companyName="Andronova Games";PlayerSettings.SplashScreen.show=false;PlayerSettings.SplashScreen.showUnityLogo=false;VoyageFontSetup.Apply();EditorSceneManager.SaveOpenScenes();string original=SceneManager.GetActiveScene().path;
 foreach(var p in Directory.GetFiles("Assets/Presentation/Resources/Voyage","*.png")){AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);var t=(TextureImporter)AssetImporter.GetAtPath(p);t.textureType=TextureImporterType.Sprite;t.spriteImportMode=SpriteImportMode.Single;t.spritePixelsPerUnit=100;t.filterMode=FilterMode.Point;t.mipmapEnabled=false;t.textureCompression=TextureImporterCompression.Uncompressed;t.alphaIsTransparency=true;t.maxTextureSize=2048;string n=Path.GetFileNameWithoutExtension(p);if(n.StartsWith("button"))t.spriteBorder=new Vector4(95,55,95,55);if(n.StartsWith("pipe_flow_")){t.spritePivot=new Vector2(.5f,1);var settings=new UnityEditor.TextureImporterSettings();t.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.Custom;settings.spritePivot=new Vector2(.5f,1);t.SetTextureSettings(settings);}if(n=="volume_track")t.spriteBorder=new Vector4(65,25,65,25);if(n=="level_header")t.spriteBorder=new Vector4(80,30,80,30);if(n=="settings")t.spriteBorder=new Vector4(100,100,100,100);t.SaveAndReimport();}
 var scene=SceneManager.GetSceneByPath("Assets/Scenes/MainMenu.unity");if(!File.Exists("Assets/Scenes/MainMenu.unity")){scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=new GameObject("Main Camera",typeof(Camera),typeof(AudioListener));go.tag="MainCamera";go.transform.position=new Vector3(0,0,-10);go.GetComponent<Camera>().orthographic=true;go.GetComponent<Camera>().orthographicSize=10;var menu=new GameObject("Main menu").AddComponent<VoyageMainMenu>();menu.teamIntro=AssetDatabase.LoadAssetAtPath<VideoClip>("Assets/andronovapixelart.mp4");EditorSceneManager.SaveScene(scene,"Assets/Scenes/MainMenu.unity");}else{scene=EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");var menu=UnityEngine.Object.FindFirstObjectByType<VoyageMainMenu>();if(!menu)menu=new GameObject("Main menu").AddComponent<VoyageMainMenu>();menu.teamIntro=AssetDatabase.LoadAssetAtPath<VideoClip>("Assets/andronovapixelart.mp4");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}
 var paths=new[]{"Assets/Scenes/MainMenu.unity",StorySceneJourney.UnderwaterPath,StorySceneJourney.ShipPath};var list=paths.Select(p=>new EditorBuildSettingsScene(p,true)).ToList();list.AddRange(EditorBuildSettings.scenes.Where(s=>!paths.Contains(s.path)&&File.Exists(s.path)));EditorBuildSettings.scenes=list.ToArray();EditorSceneManager.playModeStartScene=AssetDatabase.LoadAssetAtPath<SceneAsset>("Assets/Scenes/MainMenu.unity");if(!string.IsNullOrEmpty(original)&&File.Exists(original))EditorSceneManager.OpenScene(original);
 }
}


